var a=[{id:`01`,title:{en:`Getting started`,ua:`Перші кроки`}},{id:`02`,title:{en:`Programming fundamentals`,ua:`Основи програмування`}},{id:`03`,title:{en:`Tools and code execution`,ua:`Інструменти та запуск коду`}},{id:`04`,title:{en:`Web and networking`,ua:`Веб і мережі`}},{id:`05`,title:{en:`Data and databases`,ua:`Дані та бази даних`}},{id:`06`,title:{en:`Git and teamwork`,ua:`Git і командна робота`}},{id:`07`,title:{en:`Object-oriented programming and principles`,ua:`ООП і принципи`}},{id:`08`,title:{en:`Software architecture`,ua:`Архітектура програм`}},{id:`09`,title:{en:`Algorithms and efficiency`,ua:`Алгоритми та ефективність`}},{id:`10`,title:{en:`Testing and code quality`,ua:`Тестування та якість коду`}},{id:`11`,title:{en:`Security and access`,ua:`Безпека та доступ`}},{id:`12`,title:{en:`Deployment, cloud, and operations`,ua:`Розгортання, хмара та експлуатація`}},{id:`13`,title:{en:`Distributed systems`,ua:`Розподілені системи`}},{id:`14`,title:{en:`AI-assisted development`,ua:`Розробка з використанням ШІ`}},{id:`15`,title:{en:`Product planning and engineering decisions`,ua:`Планування продукту та технічні рішення`}}];var n=[{section:`01`,term:{en:`Code`,ua:`Код`},def:{en:`Instructions written for a computer. A developer writes code to tell software what to do.`,ua:`Інструкції для комп’ютера. Розробник пише код, щоб пояснити програмі, що потрібно робити.`},starter:!0},{section:`01`,term:{en:`Programming`,ua:`Програмування`},def:{en:`The process of creating instructions that a computer can execute.`,ua:`Процес створення інструкцій, які комп’ютер може виконати.`},starter:!1},{section:`01`,term:{en:`Program`,ua:`Програма`},def:{en:`A set of instructions that performs a task, such as calculating a price.`,ua:`Набір інструкцій для виконання завдання, наприклад обчислення ціни.`},starter:!1},{section:`01`,term:{en:`Software`,ua:`Програмне забезпечення`},def:{en:`Programs and digital systems that run on computers or phones.`,ua:`Програми й цифрові системи, що працюють на комп’ютерах або телефонах.`},starter:!0},{section:`01`,term:{en:`Hardware`,ua:`Апаратне забезпечення`},def:{en:`Physical devices such as a processor, keyboard, or phone.`,ua:`Фізичні пристрої: процесор, клавіатура, телефон тощо.`},starter:!1},{section:`01`,term:{en:`Application (app)`,ua:`Застосунок`},def:{en:`Software built to help someone do something, such as send a message or book a room.`,ua:`Програма для конкретних дій: надіслати повідомлення, забронювати номер тощо.`},starter:!0},{section:`01`,term:{en:`Website`,ua:`Вебсайт`},def:{en:`A collection of pages that people open in a web browser.`,ua:`Набір сторінок, які люди відкривають у браузері.`},starter:!1},{section:`01`,term:{en:`Web application`,ua:`Вебзастосунок`},def:{en:`A website with interactive functions, such as an online editor or banking dashboard.`,ua:`Сайт з інтерактивними функціями, наприклад онлайн-редактор або банківський кабінет.`},starter:!1},{section:`01`,term:{en:`Mobile application`,ua:`Мобільний застосунок`},def:{en:`An app designed to run on a phone or tablet.`,ua:`Застосунок, створений для роботи на телефоні чи планшеті.`},starter:!1},{section:`01`,term:{en:`Frontend`,ua:`Фронтенд`},def:{en:`The part of an app users see and interact with: pages, buttons, and forms.`,ua:`Частина застосунку, яку бачить користувач: сторінки, кнопки та форми.`},starter:!0},{section:`01`,term:{en:`Backend`,ua:`Бекенд`},def:{en:`The part of an app that handles business rules, data, and server-side operations.`,ua:`Частина застосунку, що обробляє бізнес-правила, дані та операції на сервері.`},starter:!0},{section:`01`,term:{en:`Full-stack developer`,ua:`Фулстек-розробник`},def:{en:`A developer who works on both frontend and backend.`,ua:`Розробник, який працює і з фронтендом, і з бекендом.`},starter:!1},{section:`01`,term:{en:`User`,ua:`Користувач`},def:{en:`A person who uses an application or system.`,ua:`Людина, яка користується застосунком або системою.`},starter:!1},{section:`01`,term:{en:`User interface (UI)`,ua:`Інтерфейс користувача`},def:{en:`The visible controls and screens a person uses to operate software.`,ua:`Екрани та елементи керування, через які людина взаємодіє з програмою.`},starter:!0},{section:`01`,term:{en:`User experience (UX)`,ua:`Користувацький досвід`},def:{en:`How easy, understandable, and pleasant a product is to use.`,ua:`Наскільки продукт зручний, зрозумілий і приємний у використанні.`},starter:!1},{section:`01`,term:{en:`Feature`,ua:`Функція продукту`},def:{en:`A capability an app provides, such as search or login.`,ua:`Можливість застосунку, наприклад пошук або вхід в акаунт.`},starter:!0},{section:`01`,term:{en:`Requirement`,ua:`Вимога`},def:{en:`A statement of what a product must do or what conditions it must meet.`,ua:`Опис того, що продукт має робити або яким умовам відповідати.`},starter:!1},{section:`01`,term:{en:`Bug`,ua:`Баг, помилка`},def:{en:`A problem that makes software behave incorrectly.`,ua:`Проблема, через яку програма працює неправильно.`},starter:!0},{section:`01`,term:{en:`Debugging`,ua:`Налагодження`},def:{en:`Finding the cause of a problem in code and fixing it.`,ua:`Пошук причини проблеми в коді та її виправлення.`},starter:!1},{section:`02`,term:{en:`Programming language`,ua:`Мова програмування`},def:{en:`A language with rules for expressing instructions, such as JavaScript or Python.`,ua:`Мова з правилами запису інструкцій, наприклад JavaScript або Python.`},starter:!0},{section:`02`,term:{en:`Source code`,ua:`Вихідний код`},def:{en:`The human-readable code developers write and edit.`,ua:`Код, який розробники пишуть і редагують у зрозумілому для людини вигляді.`},starter:!1},{section:`02`,term:{en:`Syntax`,ua:`Синтаксис`},def:{en:`Rules for writing valid statements in a programming language, like grammar in a human language.`,ua:`Правила правильного запису команд у мові програмування, подібні до граматики.`},starter:!1},{section:`02`,term:{en:`Variable`,ua:`Змінна`},def:{en:`A named place for a value that a program can use or change.`,ua:`Іменоване місце для значення, яке програма може читати або змінювати.`},starter:!0},{section:`02`,term:{en:`Constant`,ua:`Константа`},def:{en:`A named value that cannot be reassigned after it is set in languages with that rule.`,ua:`Іменоване значення, якому не можна призначити інше значення після створення у відповідних мовах.`},starter:!1},{section:`02`,term:{en:`Data type`,ua:`Тип даних`},def:{en:`A category of value, such as text, number, or true/false.`,ua:`Категорія значення: текст, число або так/ні.`},starter:!1},{section:`02`,term:{en:`String`,ua:`Рядок`},def:{en:`Text stored in a program, such as a person's name.`,ua:`Текстове значення у програмі, наприклад ім’я людини.`},starter:!1},{section:`02`,term:{en:`Number`,ua:`Число`},def:{en:`A numeric value used for calculations, quantities, or measurements.`,ua:`Числове значення для обчислень, кількостей чи вимірювань.`},starter:!1},{section:`02`,term:{en:`Boolean`,ua:`Булеве значення`},def:{en:`A value that can be only true or false.`,ua:`Значення, що може бути лише true (так) або false (ні).`},starter:!1},{section:`02`,term:{en:`Null`,ua:`Null, відсутнє значення`},def:{en:`An explicit way to say that a value is intentionally absent.`,ua:`Спосіб явно вказати, що значення відсутнє.`},starter:!1},{section:`02`,term:{en:`Undefined`,ua:`Undefined, невизначене`},def:{en:`In JavaScript, a value commonly meaning that something has not been assigned.`,ua:`У JavaScript означає, що значення ще не було призначене.`},starter:!1},{section:`02`,term:{en:`Function`,ua:`Функція`},def:{en:`A reusable block of code that performs a task when called.`,ua:`Повторно використовуваний блок коду, який виконує завдання під час виклику.`},starter:!0},{section:`02`,term:{en:`Parameter`,ua:`Параметр`},def:{en:`A named input defined by a function, such as “price” in a discount calculator.`,ua:`Назва вхідного значення у визначенні функції, наприклад «ціна» в калькуляторі знижок.`},starter:!1},{section:`02`,term:{en:`Argument`,ua:`Аргумент`},def:{en:`The actual value passed into a function when it is called.`,ua:`Конкретне значення, передане функції під час виклику.`},starter:!1},{section:`02`,term:{en:`Return value`,ua:`Повернене значення`},def:{en:`The result a function gives back to the code that called it.`,ua:`Результат, який функція повертає коду, що її викликав.`},starter:!1},{section:`02`,term:{en:`Condition`,ua:`Умова`},def:{en:`A check that decides which action to perform, such as “if the user is logged in”.`,ua:`Перевірка, яка визначає подальшу дію, наприклад «якщо користувач увійшов».`},starter:!0},{section:`02`,term:{en:`Loop`,ua:`Цикл`},def:{en:`A way to repeat instructions, such as checking every item in a shopping cart.`,ua:`Спосіб повторити інструкції, наприклад перевірити всі товари в кошику.`},starter:!0},{section:`02`,term:{en:`Array`,ua:`Масив`},def:{en:`An ordered collection of values, such as a list of product names.`,ua:`Впорядкований набір значень, наприклад список назв товарів.`},starter:!0},{section:`02`,term:{en:`Object`,ua:`Об’єкт`},def:{en:`A collection of related named values, such as a user with a name and email.`,ua:`Набір пов’язаних значень із назвами, наприклад користувач з ім’ям та email.`},starter:!0},{section:`02`,term:{en:`Key–value pair`,ua:`Пара «ключ — значення»`},def:{en:`A named piece of data, such as “age” paired with “25”.`,ua:`Дані, у яких назва («вік») пов’язана зі значенням («25»).`},starter:!1},{section:`02`,term:{en:`Scope`,ua:`Область видимості`},def:{en:`The part of a program where a variable or name can be accessed.`,ua:`Частина програми, де змінну або назву можна використовувати.`},starter:!1},{section:`02`,term:{en:`Callback`,ua:`Колбек, зворотний виклик`},def:{en:`A function given to other code so it can be called later, often after an event.`,ua:`Функція, передана іншому коду для виклику пізніше, часто після події.`},starter:!1},{section:`02`,term:{en:`Asynchronous`,ua:`Асинхронний`},def:{en:`Work that can be started now and completed later without blocking all other work.`,ua:`Робота, що починається зараз і завершується пізніше, не зупиняючи все інше.`},starter:!1},{section:`02`,term:{en:`Promise`,ua:`Проміс`},def:{en:`In JavaScript, an object representing a result that will become available later or fail.`,ua:`У JavaScript — об’єкт, що представляє майбутній результат або помилку.`},starter:!1},{section:`02`,term:{en:`Exception`,ua:`Виняток`},def:{en:`An error signal that interrupts normal execution unless the program handles it.`,ua:`Сигнал про помилку, який перериває звичайну роботу, якщо його не обробити.`},starter:!1},{section:`02`,term:{en:`Algorithm`,ua:`Алгоритм`},def:{en:`A step-by-step method for solving a problem, like following a recipe.`,ua:`Покроковий спосіб розв’язання задачі, подібний до рецепта.`},starter:!0},{section:`02`,term:{en:`Pseudocode`,ua:`Псевдокод`},def:{en:`A plain-language outline of an algorithm that is not meant to run directly.`,ua:`Опис алгоритму простими словами, який не призначений для прямого виконання.`},starter:!1},{section:`03`,term:{en:`Code editor`,ua:`Редактор коду`},def:{en:`A tool for writing and editing code, such as VS Code.`,ua:`Програма для написання та редагування коду, наприклад VS Code.`},starter:!1},{section:`03`,term:{en:`IDE`,ua:`Інтегроване середовище розробки`},def:{en:`A development tool combining an editor with helpers like debugging and project management.`,ua:`Програма, що об’єднує редактор, налагодження та інші інструменти розробки.`},starter:!1},{section:`03`,term:{en:`Terminal`,ua:`Термінал`},def:{en:`A text-based window for giving commands to your computer.`,ua:`Текстове вікно, у якому вводять команди для комп’ютера.`},starter:!0},{section:`03`,term:{en:`Command line (CLI)`,ua:`Командний рядок`},def:{en:`A way to control a tool by typing commands instead of clicking buttons.`,ua:`Спосіб керувати інструментом текстовими командами замість кнопок.`},starter:!1},{section:`03`,term:{en:`Shell`,ua:`Командна оболонка`},def:{en:`The program that reads commands in a terminal and runs them.`,ua:`Програма, яка читає команди в терміналі та виконує їх.`},starter:!1},{section:`03`,term:{en:`Runtime`,ua:`Середовище виконання`},def:{en:`Software needed to run a program, such as Node.js for some JavaScript apps.`,ua:`Програмне середовище для запуску коду, наприклад Node.js для JavaScript.`},starter:!0},{section:`03`,term:{en:`Compiler`,ua:`Компілятор`},def:{en:`A tool that translates code into another form before it runs.`,ua:`Інструмент, який перетворює код в іншу форму перед виконанням.`},starter:!1},{section:`03`,term:{en:`Interpreter`,ua:`Інтерпретатор`},def:{en:`Software that executes instructions by interpreting code during execution.`,ua:`Програма, яка виконує інструкції, інтерпретуючи код під час роботи.`},starter:!1},{section:`03`,term:{en:`Build`,ua:`Збірка`},def:{en:`Preparing source files into something that can be run or deployed.`,ua:`Підготовка вихідних файлів до запуску або публікації.`},starter:!0},{section:`03`,term:{en:`Bundler`,ua:`Бандлер`},def:{en:`A tool that combines and organizes code files for an application.`,ua:`Інструмент, який об’єднує й упорядковує файли коду для застосунку.`},starter:!1},{section:`03`,term:{en:`Dependency`,ua:`Залежність`},def:{en:`A library or component that a project needs in order to work.`,ua:`Бібліотека або компонент, потрібний проєкту для роботи.`},starter:!0},{section:`03`,term:{en:`Package`,ua:`Пакет`},def:{en:`A reusable piece of software distributed for other projects to install.`,ua:`Готова частина програмного забезпечення, яку можна встановити в інший проєкт.`},starter:!1},{section:`03`,term:{en:`Package manager`,ua:`Менеджер пакетів`},def:{en:`A tool that installs and updates dependencies, such as npm.`,ua:`Інструмент для встановлення й оновлення залежностей, наприклад npm.`},starter:!1},{section:`03`,term:{en:`Library`,ua:`Бібліотека`},def:{en:`Reusable code that your application calls when it needs a specific capability.`,ua:`Готовий код, який застосунок викликає для виконання певних завдань.`},starter:!0},{section:`03`,term:{en:`Framework`,ua:`Фреймворк`},def:{en:`A structured foundation for building apps; it defines many conventions for the project.`,ua:`Готова основа застосунку, яка задає структуру та правила розробки.`},starter:!0},{section:`03`,term:{en:`SDK`,ua:`Набір засобів розробки (SDK)`},def:{en:`A package of tools and libraries for building software for a platform or service.`,ua:`Набір інструментів і бібліотек для створення програм під певну платформу чи сервіс.`},starter:!1},{section:`03`,term:{en:`Configuration`,ua:`Конфігурація`},def:{en:`Settings that control how a program or tool behaves.`,ua:`Налаштування, що визначають поведінку програми чи інструмента.`},starter:!1},{section:`03`,term:{en:`Environment variable`,ua:`Змінна середовища`},def:{en:`A setting provided from outside the code, such as a server address.`,ua:`Налаштування, передане програмі ззовні, наприклад адреса сервера.`},starter:!1},{section:`03`,term:{en:`Open source`,ua:`Відкритий вихідний код`},def:{en:`Software whose source code is available to inspect and use under its license.`,ua:`Програмне забезпечення, вихідний код якого доступний для перегляду й використання за умовами ліцензії.`},starter:!1},{section:`04`,term:{en:`Browser`,ua:`Браузер`},def:{en:`An app that opens websites, such as Chrome or Firefox.`,ua:`Програма для відкриття сайтів, наприклад Chrome чи Firefox.`},starter:!0},{section:`04`,term:{en:`Client`,ua:`Клієнт`},def:{en:`An app or device that requests information from another system, often a server.`,ua:`Програма або пристрій, що запитує дані в іншої системи, зазвичай сервера.`},starter:!0},{section:`04`,term:{en:`Server`,ua:`Сервер`},def:{en:`A computer or program that responds to requests from other programs.`,ua:`Комп’ютер або програма, що відповідає на запити інших програм.`},starter:!0},{section:`04`,term:{en:`Internet`,ua:`Інтернет`},def:{en:`A worldwide network that connects computers and other devices.`,ua:`Всесвітня мережа, яка з’єднує комп’ютери та інші пристрої.`},starter:!1},{section:`04`,term:{en:`HTTP`,ua:`Протокол HTTP`},def:{en:`A set of rules used to send requests and responses on the web.`,ua:`Правила обміну запитами й відповідями у вебі.`},starter:!0},{section:`04`,term:{en:`HTTPS`,ua:`Захищений HTTP`},def:{en:`HTTP with encryption to protect data while it travels between client and server.`,ua:`HTTP із шифруванням для захисту даних під час передавання між клієнтом і сервером.`},starter:!1},{section:`04`,term:{en:`Request`,ua:`Запит`},def:{en:`A message asking another system to do something or return information.`,ua:`Повідомлення з проханням виконати дію або повернути дані.`},starter:!0},{section:`04`,term:{en:`Response`,ua:`Відповідь`},def:{en:`The message sent back after a request, such as a list of products.`,ua:`Повідомлення у відповідь на запит, наприклад список товарів.`},starter:!0},{section:`04`,term:{en:`URL`,ua:`Вебадреса (URL)`},def:{en:`An address pointing to a web resource, such as a page or API endpoint.`,ua:`Адреса вебресурсу, наприклад сторінки або API-ендпоїнта.`},starter:!1},{section:`04`,term:{en:`Domain`,ua:`Домен`},def:{en:`A human-readable internet name, such as example.com.`,ua:`Зрозуміла людині інтернет-адреса, наприклад example.com.`},starter:!1},{section:`04`,term:{en:`DNS`,ua:`Система доменних імен (DNS)`},def:{en:`A system that helps turn domain names into network addresses.`,ua:`Система, що допомагає знайти мережеву адресу за доменним ім’ям.`},starter:!1},{section:`04`,term:{en:`IP address`,ua:`IP-адреса`},def:{en:`A numeric address used to identify a device or network interface on a network.`,ua:`Числова адреса пристрою або мережевого інтерфейсу в мережі.`},starter:!1},{section:`04`,term:{en:`Port`,ua:`Мережевий порт`},def:{en:`A numbered connection point used to direct network traffic to the right service.`,ua:`Номер, що допомагає скерувати мережеве з’єднання до потрібного сервісу.`},starter:!1},{section:`04`,term:{en:`API`,ua:`Програмний інтерфейс (API)`},def:{en:`A defined way for one piece of software to interact with another.`,ua:`Узгоджений спосіб взаємодії однієї програми з іншою.`},starter:!0},{section:`04`,term:{en:`Endpoint`,ua:`Ендпоїнт`},def:{en:`A specific API address where a client can request an operation.`,ua:`Конкретна адреса API, за якою можна звернутися по певну операцію.`},starter:!0},{section:`04`,term:{en:`REST`,ua:`Архітектурний стиль REST`},def:{en:`A set of design constraints for web APIs that use resources and standard HTTP behavior.`,ua:`Набір принципів побудови веб-API навколо ресурсів і стандартної поведінки HTTP.`},starter:!1},{section:`04`,term:{en:`JSON`,ua:`Формат JSON`},def:{en:`A text format for structured data, often used when APIs exchange information.`,ua:`Текстовий формат структурованих даних, який часто використовують API.`},starter:!0},{section:`04`,term:{en:`HTML`,ua:`Мова розмітки HTML`},def:{en:`The markup used to describe the content and structure of web pages.`,ua:`Мова розмітки, яка описує вміст і структуру вебсторінки.`},starter:!1},{section:`04`,term:{en:`CSS`,ua:`Таблиці стилів CSS`},def:{en:`Rules that control how a web page looks, including colors and layout.`,ua:`Правила оформлення сторінки: кольори, розташування елементів тощо.`},starter:!1},{section:`04`,term:{en:`JavaScript`,ua:`JavaScript`},def:{en:`A programming language widely used to make web pages interactive.`,ua:`Мова програмування, яку широко використовують для інтерактивності вебсторінок.`},starter:!1},{section:`04`,term:{en:`TypeScript`,ua:`TypeScript`},def:{en:`A language based on JavaScript that adds static type checking.`,ua:`Мова на основі JavaScript із перевіркою типів до запуску програми.`},starter:!1},{section:`04`,term:{en:`SPA`,ua:`Односторінковий застосунок (SPA)`},def:{en:`A web app that updates its interface without loading a completely new page for each action.`,ua:`Вебзастосунок, що оновлює інтерфейс без повного завантаження нової сторінки щоразу.`},starter:!1},{section:`04`,term:{en:`SSR`,ua:`Серверний рендеринг (SSR)`},def:{en:`Generating page HTML on the server before sending it to the browser.`,ua:`Створення HTML сторінки на сервері перед надсиланням у браузер.`},starter:!1},{section:`04`,term:{en:`Cookie`,ua:`Кукі`},def:{en:`A small piece of data a website asks a browser to store, often for sessions or preferences.`,ua:`Невеликий запис, який сайт зберігає у браузері, наприклад для сесії чи налаштувань.`},starter:!1},{section:`04`,term:{en:`WebSocket`,ua:`WebSocket`},def:{en:`A connection that lets client and server exchange messages in both directions without opening a new HTTP request each time.`,ua:`З’єднання, через яке клієнт і сервер обмінюються повідомленнями в обидва боки без нового HTTP-запиту щоразу.`},starter:!1},{section:`04`,term:{en:`DOM`,ua:`Об’єктна модель документа (DOM)`},def:{en:`A tree-like representation of a web page that JavaScript can read and change.`,ua:`Деревоподібне представлення вебсторінки, яке JavaScript може читати та змінювати.`},starter:!1},{section:`04`,term:{en:`Responsive design`,ua:`Адаптивний дизайн`},def:{en:`Designing pages that work well on different screen sizes, from phones to desktops.`,ua:`Створення сторінок, зручних на екранах різного розміру — від телефона до комп’ютера.`},starter:!1},{section:`04`,term:{en:`Accessibility (a11y)`,ua:`Доступність інтерфейсу`},def:{en:`Making software usable by people with different abilities, including keyboard and screen-reader users.`,ua:`Створення інтерфейсу, яким можуть користуватися люди з різними можливостями, зокрема з клавіатурою та скрінридером.`},starter:!1},{section:`04`,term:{en:`Routing`,ua:`Маршрутизація`},def:{en:`Choosing which page or handler responds to a given URL.`,ua:`Визначення, яку сторінку чи обробник показати для певної адреси.`},starter:!1},{section:`04`,term:{en:`HTTP method`,ua:`Метод HTTP`},def:{en:`A request action such as GET to read data or POST to submit data.`,ua:`Тип дії запиту: наприклад GET для отримання даних або POST для надсилання.`},starter:!1},{section:`04`,term:{en:`HTTP status code`,ua:`Код стану HTTP`},def:{en:`A number indicating a request result, such as 200 for success or 404 for not found.`,ua:`Число з результатом запиту: наприклад 200 — успіх, 404 — не знайдено.`},starter:!1},{section:`04`,term:{en:`CORS`,ua:`Правила міждоменного доступу (CORS)`},def:{en:`A browser security mechanism that controls which other origins may read responses from a server.`,ua:`Механізм безпеки браузера, який визначає, які інші джерела можуть читати відповіді сервера.`},starter:!1},{section:`04`,term:{en:`Webhook`,ua:`Вебхук`},def:{en:`An HTTP message one system automatically sends to another when something happens.`,ua:`HTTP-повідомлення, яке одна система автоматично надсилає іншій після певної події.`},starter:!1},{section:`04`,term:{en:`Pagination`,ua:`Посторінкова видача`},def:{en:`Showing a large list in smaller chunks, such as 20 products per page.`,ua:`Поділ великого списку на частини, наприклад по 20 товарів на сторінці.`},starter:!1},{section:`04`,term:{en:`Rate limiting`,ua:`Обмеження частоти запитів`},def:{en:`Limiting how many requests a user or client can make in a period.`,ua:`Обмеження кількості запитів від користувача чи клієнта за певний час.`},starter:!1},{section:`05`,term:{en:`Data`,ua:`Дані`},def:{en:`Information a program stores or processes, such as names, prices, and dates.`,ua:`Інформація, яку програма зберігає або обробляє: імена, ціни, дати.`},starter:!1},{section:`05`,term:{en:`Database`,ua:`База даних`},def:{en:`An organized place for storing and retrieving information.`,ua:`Організоване сховище для збереження та пошуку інформації.`},starter:!0},{section:`05`,term:{en:`DBMS`,ua:`Система керування базами даних (СКБД)`},def:{en:`Software that manages a database, such as PostgreSQL or MongoDB.`,ua:`Програма, що керує базою даних, наприклад PostgreSQL або MongoDB.`},starter:!1},{section:`05`,term:{en:`SQL`,ua:`Мова запитів SQL`},def:{en:`A language for working with relational databases.`,ua:`Мова для роботи з реляційними базами даних.`},starter:!1},{section:`05`,term:{en:`NoSQL`,ua:`Нереляційні підходи до БД (NoSQL)`},def:{en:`A broad category of database systems that do not primarily use the classic relational-table model.`,ua:`Широка група баз даних, що не спираються передусім на класичні реляційні таблиці.`},starter:!1},{section:`05`,term:{en:`Table`,ua:`Таблиця`},def:{en:`A collection of records arranged in rows and columns in a relational database.`,ua:`Набір записів у вигляді рядків і стовпців у реляційній базі даних.`},starter:!1},{section:`05`,term:{en:`Row`,ua:`Рядок таблиці`},def:{en:`One record in a database table, such as a particular customer.`,ua:`Один запис у таблиці, наприклад конкретний клієнт.`},starter:!1},{section:`05`,term:{en:`Column`,ua:`Стовпець таблиці`},def:{en:`A named kind of information stored for records, such as “email”.`,ua:`Назване поле даних у таблиці, наприклад «email».`},starter:!1},{section:`05`,term:{en:`Document`,ua:`Документ БД`},def:{en:`A structured record in a document database, often similar to a JSON object.`,ua:`Структурований запис у документній базі даних, часто схожий на JSON-об’єкт.`},starter:!1},{section:`05`,term:{en:`Collection`,ua:`Колекція`},def:{en:`A group of documents stored together in a document database.`,ua:`Група документів, які зберігаються разом у документній базі даних.`},starter:!1},{section:`05`,term:{en:`Schema`,ua:`Схема даних`},def:{en:`A description of what data looks like and what rules it must follow.`,ua:`Опис структури даних і правил, яким вони мають відповідати.`},starter:!1},{section:`05`,term:{en:`Query`,ua:`Запит до бази даних`},def:{en:`An instruction to read or change data in a database.`,ua:`Інструкція для читання або зміни даних у базі.`},starter:!0},{section:`05`,term:{en:`Filter`,ua:`Фільтр`},def:{en:`A condition that selects only matching items, such as orders from today.`,ua:`Умова відбору потрібних записів, наприклад замовлень за сьогодні.`},starter:!1},{section:`05`,term:{en:`Index`,ua:`Індекс БД`},def:{en:`An additional data structure that helps a database find records faster, at some storage and write cost.`,ua:`Додаткова структура, що прискорює пошук записів, але потребує пам’яті та роботи під час запису.`},starter:!1},{section:`05`,term:{en:`Primary key`,ua:`Первинний ключ`},def:{en:`A field or group of fields that uniquely identifies a row.`,ua:`Поле або набір полів, що однозначно визначає рядок.`},starter:!1},{section:`05`,term:{en:`Foreign key`,ua:`Зовнішній ключ`},def:{en:`A field constrained to refer to a key in another table.`,ua:`Поле, яке за правилами БД посилається на ключ в іншій таблиці.`},starter:!1},{section:`05`,term:{en:`Relationship`,ua:`Зв’язок між даними`},def:{en:`A connection between records, such as an order belonging to a customer.`,ua:`Зв’язок між записами, наприклад замовлення належить клієнту.`},starter:!1},{section:`05`,term:{en:`CRUD`,ua:`Створення, читання, оновлення, видалення`},def:{en:`The four common data operations: Create, Read, Update, Delete.`,ua:`Чотири базові операції з даними: створити, прочитати, оновити, видалити.`},starter:!0},{section:`05`,term:{en:`Migration`,ua:`Міграція даних або схеми`},def:{en:`A controlled change to a database structure or stored data.`,ua:`Керована зміна структури бази даних або вже збережених даних.`},starter:!1},{section:`05`,term:{en:`Transaction`,ua:`Транзакція`},def:{en:`A group of database operations treated as one logical unit of work.`,ua:`Група операцій із базою, яку розглядають як одну логічну дію.`},starter:!1},{section:`05`,term:{en:`Normalization`,ua:`Нормалізація`},def:{en:`Organizing relational data to reduce duplication and prevent update mistakes.`,ua:`Організація реляційних даних, щоб зменшити дублювання й помилки оновлення.`},starter:!1},{section:`05`,term:{en:`Denormalization`,ua:`Денормалізація`},def:{en:`Intentionally duplicating or reshaping data to make certain reads faster or simpler.`,ua:`Свідоме дублювання чи перебудова даних, щоб спростити або прискорити читання.`},starter:!1},{section:`05`,term:{en:`Cache`,ua:`Кеш`},def:{en:`A temporary store of data that is quicker to access than the original source.`,ua:`Тимчасове сховище даних, до яких можна звернутися швидше, ніж до першоджерела.`},starter:!1},{section:`05`,term:{en:`Backup`,ua:`Резервна копія`},def:{en:`A saved copy of data used to restore it if something goes wrong.`,ua:`Збережена копія даних для відновлення після проблеми.`},starter:!1},{section:`05`,term:{en:`ORM`,ua:`Об’єктно-реляційне відображення (ORM)`},def:{en:`A tool that maps program objects to database tables and helps work with them.`,ua:`Інструмент, що зіставляє об’єкти програми з таблицями БД і спрощує роботу з ними.`},starter:!1},{section:`05`,term:{en:`Data validation`,ua:`Перевірка даних`},def:{en:`Checking that incoming data meets rules, such as an email having a valid shape.`,ua:`Перевірка відповідності даних правилам, наприклад правильності формату email.`},starter:!1},{section:`06`,term:{en:`Version control`,ua:`Контроль версій`},def:{en:`A way to record changes in files so a team can see history and restore older versions.`,ua:`Спосіб зберігати історію змін файлів, переглядати її та повертатися до старіших версій.`},starter:!1},{section:`06`,term:{en:`Git`,ua:`Git`},def:{en:`A widely used version-control system for tracking code changes.`,ua:`Популярна система контролю версій, що відстежує зміни в коді.`},starter:!0},{section:`06`,term:{en:`Repository (repo)`,ua:`Репозиторій`},def:{en:`A project folder tracked by version control, including its change history.`,ua:`Папка проєкту під контролем версій разом з історією змін.`},starter:!0},{section:`06`,term:{en:`Commit`,ua:`Коміт`},def:{en:`A saved snapshot of changes in a Git repository, usually with a short description.`,ua:`Збережений набір змін у Git, зазвичай із коротким поясненням.`},starter:!0},{section:`06`,term:{en:`Branch`,ua:`Гілка`},def:{en:`An independent line of work in Git, often used for a new feature.`,ua:`Окрема лінія розробки в Git, наприклад для нової функції.`},starter:!0},{section:`06`,term:{en:`Merge`,ua:`Злиття гілок`},def:{en:`Combining changes from one Git branch with another.`,ua:`Об’єднання змін з однієї гілки Git з іншою.`},starter:!1},{section:`06`,term:{en:`Pull request (PR)`,ua:`Запит на злиття (PR)`},def:{en:`A request to review changes before merging them into a shared branch.`,ua:`Запит на перевірку змін перед їхнім злиттям у спільну гілку.`},starter:!1},{section:`06`,term:{en:`Code review`,ua:`Перевірка коду`},def:{en:`Examining code for correctness, readability, security, and design before accepting it.`,ua:`Перевірка коду на правильність, зрозумілість, безпеку та якість рішень.`},starter:!1},{section:`06`,term:{en:`Clone`,ua:`Клонування`},def:{en:`Creating a local copy of an existing Git repository.`,ua:`Створення локальної копії наявного Git-репозиторію.`},starter:!1},{section:`06`,term:{en:`Pull`,ua:`Отримати зміни (pull)`},def:{en:`Fetching remote changes and integrating them into the local branch.`,ua:`Отримання змін із віддаленого репозиторію та інтеграція їх у локальну гілку.`},starter:!1},{section:`06`,term:{en:`Push`,ua:`Надіслати зміни (push)`},def:{en:`Sending local Git commits to a remote repository.`,ua:`Надсилання локальних комітів Git до віддаленого репозиторію.`},starter:!1},{section:`06`,term:{en:`Merge conflict`,ua:`Конфлікт злиття`},def:{en:`A situation where Git needs a person to decide how incompatible changes should combine.`,ua:`Ситуація, коли Git потребує рішення людини для об’єднання несумісних змін.`},starter:!1},{section:`06`,term:{en:`Diff`,ua:`Різниця між версіями`},def:{en:`A view showing what lines were added, removed, or changed.`,ua:`Порівняння, яке показує додані, видалені та змінені рядки.`},starter:!1},{section:`06`,term:{en:`Issue`,ua:`Задача або проблема`},def:{en:`A tracked task, bug report, or feature request in a project.`,ua:`Зареєстрована задача, повідомлення про помилку чи пропозиція функції.`},starter:!1},{section:`06`,term:{en:`README`,ua:`Файл README`},def:{en:`A file that explains what a project is and how to use or run it.`,ua:`Файл із поясненням призначення проєкту та інструкціями щодо запуску.`},starter:!1},{section:`06`,term:{en:`Documentation`,ua:`Документація`},def:{en:`Written explanations of how software works, how to use it, or why it was designed a certain way.`,ua:`Текстові пояснення роботи програми, її використання та причин архітектурних рішень.`},starter:!1},{section:`06`,term:{en:`Release`,ua:`Реліз, випуск`},def:{en:`A published version of software prepared for users or developers.`,ua:`Опублікована версія програми для користувачів або інших розробників.`},starter:!1},{section:`06`,term:{en:`Semantic versioning`,ua:`Семантичне версіонування`},def:{en:`A version-number convention such as 2.4.1 that communicates breaking, feature, and fix changes.`,ua:`Правило версій на кшталт 2.4.1, яке розрізняє несумісні зміни, нові можливості та виправлення.`},starter:!1},{section:`06`,term:{en:`Changelog`,ua:`Історія змін`},def:{en:`A document listing important changes between software versions.`,ua:`Документ з описом важливих змін між версіями програми.`},starter:!1},{section:`07`,term:{en:`Object-oriented programming (OOP)`,ua:`Об’єктноорієнтоване програмування (ООП)`},def:{en:`A way to organize software around objects that combine data and behavior.`,ua:`Підхід, за якого програму організовують навколо об’єктів із даними та поведінкою.`},starter:!1},{section:`07`,term:{en:`Class`,ua:`Клас`},def:{en:`A definition used to create objects with a common structure or behavior.`,ua:`Опис, за яким створюють об’єкти зі спільною структурою чи поведінкою.`},starter:!1},{section:`07`,term:{en:`Instance`,ua:`Екземпляр`},def:{en:`A particular object created from a class, such as one specific customer.`,ua:`Конкретний об’єкт, створений за описом класу, наприклад певний клієнт.`},starter:!1},{section:`07`,term:{en:`Property`,ua:`Властивість`},def:{en:`A named value stored on an object, such as a product's price.`,ua:`Іменоване значення об’єкта, наприклад ціна товару.`},starter:!1},{section:`07`,term:{en:`Method`,ua:`Метод`},def:{en:`A function associated with an object or class.`,ua:`Функція, пов’язана з об’єктом або класом.`},starter:!1},{section:`07`,term:{en:`Constructor`,ua:`Конструктор`},def:{en:`Code used to initialize a new object when it is created.`,ua:`Код, що встановлює початковий стан нового об’єкта під час створення.`},starter:!1},{section:`07`,term:{en:`Encapsulation`,ua:`Інкапсуляція`},def:{en:`Keeping an object's internal details controlled and exposing a clear way to use it.`,ua:`Приховування внутрішніх деталей об’єкта й надання зрозумілого способу роботи з ним.`},starter:!1},{section:`07`,term:{en:`Inheritance`,ua:`Успадкування`},def:{en:`Creating a new class based on another class to reuse or extend behavior.`,ua:`Створення нового класу на основі іншого для повторного використання чи розширення поведінки.`},starter:!1},{section:`07`,term:{en:`Polymorphism`,ua:`Поліморфізм`},def:{en:`Using different objects through a shared interface while each can behave differently.`,ua:`Робота з різними об’єктами через спільний інтерфейс, хоча поведінка може відрізнятися.`},starter:!1},{section:`07`,term:{en:`Abstraction`,ua:`Абстракція`},def:{en:`Showing the important idea while hiding unnecessary implementation details.`,ua:`Виділення головного та приховування зайвих деталей реалізації.`},starter:!1},{section:`07`,term:{en:`Interface`,ua:`Інтерфейс у коді`},def:{en:`A contract describing what operations or properties something must provide.`,ua:`Контракт, що описує потрібні операції або властивості певної сутності.`},starter:!1},{section:`07`,term:{en:`Implementation`,ua:`Реалізація`},def:{en:`The actual code that fulfills a defined behavior or interface.`,ua:`Конкретний код, який виконує поведінку або вимоги інтерфейсу.`},starter:!1},{section:`07`,term:{en:`Composition`,ua:`Композиція`},def:{en:`Building a larger behavior from smaller parts instead of relying only on inheritance.`,ua:`Складання більшої функціональності з менших частин замість опори лише на успадкування.`},starter:!1},{section:`07`,term:{en:`Dependency injection (DI)`,ua:`Впровадження залежностей`},def:{en:`Giving an object the services it needs from outside instead of making it create them itself.`,ua:`Передавання об’єкту потрібних сервісів ззовні, а не створення їх усередині.`},starter:!1},{section:`07`,term:{en:`SOLID`,ua:`Принципи SOLID`},def:{en:`Five principles that help make object-oriented code easier to change and test.`,ua:`П’ять принципів, які допомагають робити ООП-код зручнішим для змін і тестування.`},starter:!1},{section:`07`,term:{en:`Single Responsibility Principle (SRP)`,ua:`Принцип єдиної відповідальності`},def:{en:`A module should have one coherent responsibility and one main reason to change.`,ua:`Модуль має мати одну цілісну відповідальність і одну головну причину змінюватися.`},starter:!1},{section:`07`,term:{en:`Open/Closed Principle (OCP)`,ua:`Принцип відкритості/закритості`},def:{en:`Design components so new behavior can often be added without editing stable existing code.`,ua:`Проєктуйте компоненти так, щоб нову поведінку часто можна було додати без зміни стабільного коду.`},starter:!1},{section:`07`,term:{en:`Liskov Substitution Principle (LSP)`,ua:`Принцип підстановки Лісков`},def:{en:`A subtype should be usable wherever its base type is expected without breaking promises.`,ua:`Підтип має працювати замість базового типу, не порушуючи обіцяної поведінки.`},starter:!1},{section:`07`,term:{en:`Interface Segregation Principle (ISP)`,ua:`Принцип розділення інтерфейсів`},def:{en:`Clients should not be forced to depend on operations they do not need.`,ua:`Клієнтський код не повинен залежати від непотрібних йому операцій.`},starter:!1},{section:`07`,term:{en:`Dependency Inversion Principle (DIP)`,ua:`Принцип інверсії залежностей`},def:{en:`High-level policy should depend on abstractions rather than concrete low-level details.`,ua:`Високорівнева логіка має залежати від абстракцій, а не від конкретних технічних деталей.`},starter:!1},{section:`07`,term:{en:`DRY`,ua:`Не повторюй знання (DRY)`},def:{en:`Keep one clear source of truth for knowledge or rules rather than duplicating them.`,ua:`Зберігайте правило чи знання в одному визначеному місці замість його дублювання.`},starter:!1},{section:`07`,term:{en:`KISS`,ua:`Роби простіше (KISS)`},def:{en:`Choose the simplest design that solves the real problem adequately.`,ua:`Обирайте найпростіше рішення, яке достатньо добре розв’язує реальну проблему.`},starter:!1},{section:`07`,term:{en:`YAGNI`,ua:`Не роби наперед (YAGNI)`},def:{en:`Avoid building features or complexity until there is a real need.`,ua:`Не додавайте функції та складність, доки в них немає реальної потреби.`},starter:!1},{section:`07`,term:{en:`Separation of concerns (SoC)`,ua:`Розділення відповідальностей`},def:{en:`Keep different responsibilities in different parts of the system.`,ua:`Розміщуйте різні обов’язки в різних частинах системи.`},starter:!1},{section:`07`,term:{en:`Design pattern`,ua:`Шаблон проєктування`},def:{en:`A reusable idea for solving a recurring software-design problem.`,ua:`Повторно використовувана ідея розв’язання типової проблеми проєктування програм.`},starter:!1},{section:`07`,term:{en:`GRASP`,ua:`Принципи GRASP`},def:{en:`Guidelines for deciding which class or object should handle a responsibility.`,ua:`Принципи вибору класу чи об’єкта, якому слід доручити певну відповідальність.`},starter:!1},{section:`07`,term:{en:`Factory pattern`,ua:`Шаблон Factory`},def:{en:`A design approach that moves object creation into a dedicated function or component.`,ua:`Підхід, за якого створення об’єктів виносять в окрему функцію чи компонент.`},starter:!1},{section:`07`,term:{en:`Strategy pattern`,ua:`Шаблон Strategy`},def:{en:`A pattern that lets a program swap between different ways to perform the same task.`,ua:`Шаблон, що дозволяє змінювати спосіб виконання тієї самої задачі.`},starter:!1},{section:`07`,term:{en:`Observer pattern`,ua:`Шаблон Observer`},def:{en:`A pattern where interested objects are notified when something changes.`,ua:`Шаблон, за яким зацікавлені об’єкти отримують повідомлення про зміни.`},starter:!1},{section:`08`,term:{en:`Software architecture`,ua:`Архітектура програмного забезпечення`},def:{en:`The major design decisions about how a system is divided and how its parts work together.`,ua:`Основні рішення щодо поділу системи на частини та їхньої взаємодії.`},starter:!1},{section:`08`,term:{en:`Module`,ua:`Модуль`},def:{en:`A relatively independent part of a system that groups related functionality.`,ua:`Відносно самостійна частина системи, яка об’єднує пов’язану функціональність.`},starter:!1},{section:`08`,term:{en:`Component`,ua:`Компонент`},def:{en:`A part of software with a clear role and a defined way to interact with other parts.`,ua:`Частина програми з конкретним призначенням і визначеним способом взаємодії з іншими.`},starter:!1},{section:`08`,term:{en:`Layer`,ua:`Шар архітектури`},def:{en:`A level of a system responsible for a particular kind of work, such as presentation or data access.`,ua:`Рівень системи, що відповідає за певний тип роботи, наприклад інтерфейс чи доступ до даних.`},starter:!1},{section:`08`,term:{en:`Coupling`,ua:`Зв’язаність`},def:{en:`How strongly parts of a system depend on each other; less unnecessary coupling makes changes easier.`,ua:`Наскільки сильно частини системи залежать одна від одної; менше зайвих залежностей полегшує зміни.`},starter:!1},{section:`08`,term:{en:`Cohesion`,ua:`Згуртованість`},def:{en:`How closely the tasks inside one module belong together; high cohesion is usually desirable.`,ua:`Наскільки тісно пов’язані задачі всередині модуля; висока згуртованість зазвичай корисна.`},starter:!1},{section:`08`,term:{en:`Monolith`,ua:`Моноліт`},def:{en:`An application built and deployed as one main unit.`,ua:`Застосунок, який створюють і розгортають як одну основну одиницю.`},starter:!1},{section:`08`,term:{en:`Modular monolith`,ua:`Модульний моноліт`},def:{en:`One deployable application with well-defined internal modules and boundaries.`,ua:`Один застосунок для розгортання, але з чіткими внутрішніми модулями та межами.`},starter:!1},{section:`08`,term:{en:`Microservice`,ua:`Мікросервіс`},def:{en:`A separately deployable service focused on a particular business capability.`,ua:`Окремо розгортаний сервіс для певної бізнес-можливості.`},starter:!1},{section:`08`,term:{en:`Clean Architecture`,ua:`Чиста архітектура`},def:{en:`An approach that keeps core business rules independent of UI, databases, and frameworks.`,ua:`Підхід, де основні бізнес-правила не залежать від інтерфейсу, бази даних та фреймворків.`},starter:!1},{section:`08`,term:{en:`Hexagonal Architecture`,ua:`Гексагональна архітектура`},def:{en:`An approach that connects core application logic to external systems through ports and adapters.`,ua:`Підхід, де основна логіка взаємодіє із зовнішніми системами через порти та адаптери.`},starter:!1},{section:`08`,term:{en:`Business domain`,ua:`Предметна область`},def:{en:`The real-world area the software deals with, such as hotel bookings or payroll.`,ua:`Сфера реального світу, яку обслуговує програма, наприклад бронювання готелів.`},starter:!1},{section:`08`,term:{en:`Business logic`,ua:`Бізнес-логіка`},def:{en:`Rules that describe how a business process must behave, such as refund eligibility.`,ua:`Правила роботи процесів, наприклад коли клієнту дозволено повернення коштів.`},starter:!1},{section:`08`,term:{en:`Service`,ua:`Сервіс`},def:{en:`A component responsible for a specific capability or piece of application logic.`,ua:`Компонент, відповідальний за конкретну можливість або частину логіки застосунку.`},starter:!1},{section:`08`,term:{en:`Controller`,ua:`Контролер`},def:{en:`Code that receives an incoming request or UI action and passes work to the right logic.`,ua:`Код, що приймає запит або дію користувача та передає її потрібній логіці.`},starter:!1},{section:`08`,term:{en:`Repository pattern`,ua:`Шаблон Repository`},def:{en:`An abstraction that gives application code a consistent way to access stored data.`,ua:`Абстракція, що надає коду узгоджений спосіб доступу до збережених даних.`},starter:!1},{section:`08`,term:{en:`DTO`,ua:`Об’єкт передавання даних (DTO)`},def:{en:`A defined data shape used to move information between parts of a system.`,ua:`Визначена структура даних для передавання інформації між частинами системи.`},starter:!1},{section:`08`,term:{en:`Middleware`,ua:`Проміжний обробник`},def:{en:`Code that processes requests between receiving them and sending a response.`,ua:`Код, який обробляє запит на шляху від отримання до відповіді.`},starter:!1},{section:`08`,term:{en:`Event`,ua:`Подія`},def:{en:`A record that something happened, such as “PaymentCompleted”.`,ua:`Повідомлення про те, що щось сталося, наприклад «Оплату завершено».`},starter:!1},{section:`08`,term:{en:`Event-driven architecture`,ua:`Подієва архітектура`},def:{en:`An architecture where components react to events instead of only calling one another directly.`,ua:`Архітектура, у якій частини системи реагують на події, а не лише викликають одна одну напряму.`},starter:!1},{section:`08`,term:{en:`Message queue`,ua:`Черга повідомлень`},def:{en:`A system that holds messages until another part of the system processes them.`,ua:`Система, що зберігає повідомлення до моменту їх обробки іншою частиною програми.`},starter:!1},{section:`08`,term:{en:`Publish/subscribe (pub/sub)`,ua:`Публікація та підписка`},def:{en:`A pattern where publishers send events and subscribers receive the events they are interested in.`,ua:`Підхід, де одні компоненти публікують події, а інші отримують ті, на які підписалися.`},starter:!1},{section:`08`,term:{en:`MVC`,ua:`Модель — Представлення — Контролер`},def:{en:`A pattern separating data and rules, the user interface, and input handling.`,ua:`Шаблон поділу даних і правил, відображення та обробки дій користувача.`},starter:!1},{section:`08`,term:{en:`DDD`,ua:`Предметно-орієнтоване проєктування (DDD)`},def:{en:`An approach that models software around real business concepts and their boundaries.`,ua:`Підхід, який будує модель програми навколо реальних бізнес-понять і їхніх меж.`},starter:!1},{section:`08`,term:{en:`CQRS`,ua:`Розділення команд і запитів (CQRS)`},def:{en:`Separating the model or path for changing data from the model or path for reading it.`,ua:`Розділення способів зміни даних і їх читання, іноді з різними моделями.`},starter:!1},{section:`08`,term:{en:`Event sourcing`,ua:`Збереження стану через події`},def:{en:`Storing a history of changes as events so the current state can be reconstructed.`,ua:`Збереження історії змін у вигляді подій, з яких можна відновити поточний стан.`},starter:!1},{section:`08`,term:{en:`Design trade-off`,ua:`Компроміс у проєктуванні`},def:{en:`A choice that improves something while sacrificing something else, such as speed for simplicity.`,ua:`Вибір, за якого ми покращуємо щось одне ціною іншого, наприклад швидкість ціною простоти.`},starter:!1},{section:`08`,term:{en:`State`,ua:`Стан застосунку`},def:{en:`The information describing what is currently happening, such as items in the cart.`,ua:`Дані про поточну ситуацію в застосунку, наприклад товари в кошику.`},starter:!1},{section:`08`,term:{en:`Adapter pattern`,ua:`Шаблон Adapter`},def:{en:`A component that translates one interface into another so incompatible parts can work together.`,ua:`Компонент, що перетворює один інтерфейс на інший для взаємодії несумісних частин.`},starter:!1},{section:`09`,term:{en:`Data structure`,ua:`Структура даних`},def:{en:`A way to organize data so operations like searching or adding items are efficient.`,ua:`Спосіб організації даних для ефективного пошуку, додавання та інших дій.`},starter:!1},{section:`09`,term:{en:`Big O notation`,ua:`Позначення Big O`},def:{en:`A way to describe how an algorithm's resource needs grow as input size increases.`,ua:`Спосіб описати, як зростають витрати алгоритму зі збільшенням кількості даних.`},starter:!1},{section:`09`,term:{en:`Time complexity`,ua:`Часова складність`},def:{en:`How an algorithm's running time grows as the amount of input grows.`,ua:`Як змінюється час роботи алгоритму зі збільшенням обсягу вхідних даних.`},starter:!1},{section:`09`,term:{en:`Space complexity`,ua:`Просторова складність`},def:{en:`How much additional memory an algorithm needs as input grows.`,ua:`Скільки додаткової пам’яті потрібно алгоритму зі зростанням обсягу даних.`},starter:!1},{section:`09`,term:{en:`Stack`,ua:`Стек`},def:{en:`A collection where the most recently added item is removed first, like a stack of plates.`,ua:`Набір, з якого останній доданий елемент забирають першим, як зі стопки тарілок.`},starter:!1},{section:`09`,term:{en:`Queue`,ua:`Черга`},def:{en:`A collection where items are typically handled in arrival order.`,ua:`Набір, у якому елементи зазвичай обробляють у порядку надходження.`},starter:!1},{section:`09`,term:{en:`Linked list`,ua:`Зв’язаний список`},def:{en:`A chain of elements where each element refers to the next one.`,ua:`Ланцюжок елементів, у якому кожен вказує на наступний.`},starter:!1},{section:`09`,term:{en:`Hash map`,ua:`Хеш-таблиця`},def:{en:`A data structure that quickly finds values by keys in typical situations.`,ua:`Структура даних, що зазвичай швидко знаходить значення за ключем.`},starter:!1},{section:`09`,term:{en:`Tree`,ua:`Дерево`},def:{en:`A structure with parent-child relationships, like folders inside folders.`,ua:`Структура зі зв’язками «батько — нащадок», як папки всередині папок.`},starter:!1},{section:`09`,term:{en:`Graph`,ua:`Граф`},def:{en:`A collection of connected points, useful for roads, friendships, and dependencies.`,ua:`Набір пов’язаних точок, зручний для моделювання доріг, дружби та залежностей.`},starter:!1},{section:`09`,term:{en:`Sorting`,ua:`Сортування`},def:{en:`Putting items in a chosen order, such as cheapest to most expensive.`,ua:`Упорядкування елементів, наприклад від найдешевшого до найдорожчого.`},starter:!1},{section:`09`,term:{en:`Searching`,ua:`Пошук`},def:{en:`Finding an item or information in a collection.`,ua:`Знаходження потрібного елемента чи інформації в наборі.`},starter:!1},{section:`09`,term:{en:`Recursion`,ua:`Рекурсія`},def:{en:`A technique where a function solves a problem by calling itself on a smaller version of it.`,ua:`Підхід, у якому функція викликає себе для меншої версії задачі.`},starter:!1},{section:`09`,term:{en:`Dynamic programming`,ua:`Динамічне програмування`},def:{en:`Solving a problem by reusing results of smaller overlapping subproblems.`,ua:`Розв’язання задачі з повторним використанням результатів менших підзадач.`},starter:!1},{section:`09`,term:{en:`Greedy algorithm`,ua:`Жадібний алгоритм`},def:{en:`A strategy that makes a locally best choice at each step; it is not always globally optimal.`,ua:`Стратегія, що обирає найкращий на поточному кроці варіант, але не завжди знаходить глобальний оптимум.`},starter:!1},{section:`09`,term:{en:`Optimization`,ua:`Оптимізація`},def:{en:`Improving a program's speed, memory use, cost, or another measured quality.`,ua:`Покращення швидкості, використання пам’яті, вартості чи іншого показника програми.`},starter:!1},{section:`09`,term:{en:`Latency`,ua:`Затримка`},def:{en:`The time it takes for one operation or request to complete.`,ua:`Час виконання однієї операції чи запиту.`},starter:!1},{section:`09`,term:{en:`Throughput`,ua:`Пропускна здатність`},def:{en:`How many operations a system completes in a given period.`,ua:`Кількість операцій, які система завершує за певний час.`},starter:!1},{section:`09`,term:{en:`Bottleneck`,ua:`Вузьке місце`},def:{en:`The slowest or most limited part that holds back overall performance.`,ua:`Найповільніша або найбільш обмежена частина, що стримує всю систему.`},starter:!1},{section:`09`,term:{en:`Scalability`,ua:`Масштабованість`},def:{en:`A system's ability to handle increased demand by adding or improving resources.`,ua:`Здатність системи обробляти більше навантаження завдяки збільшенню чи покращенню ресурсів.`},starter:!1},{section:`10`,term:{en:`Test`,ua:`Тест`},def:{en:`A check that software behaves as expected under specified conditions.`,ua:`Перевірка, чи працює програма очікуваним чином за певних умов.`},starter:!0},{section:`10`,term:{en:`Unit test`,ua:`Модульний тест`},def:{en:`A test of a small unit of code, usually isolated from unrelated systems.`,ua:`Тест невеликої частини коду, зазвичай ізольованої від сторонніх систем.`},starter:!1},{section:`10`,term:{en:`Integration test`,ua:`Інтеграційний тест`},def:{en:`A test that checks whether multiple parts work together correctly.`,ua:`Тест, який перевіряє правильну взаємодію кількох частин системи.`},starter:!1},{section:`10`,term:{en:`End-to-end test (E2E)`,ua:`Наскрізний тест (E2E)`},def:{en:`A test of a complete user flow, such as logging in and placing an order.`,ua:`Тест повного сценарію користувача, наприклад входу та оформлення замовлення.`},starter:!1},{section:`10`,term:{en:`Assertion`,ua:`Твердження в тесті`},def:{en:`A check comparing an actual result with an expected result.`,ua:`Перевірка того, чи збігається фактичний результат з очікуваним.`},starter:!1},{section:`10`,term:{en:`Test case`,ua:`Тестовий випадок`},def:{en:`A specific scenario with steps, inputs, and an expected outcome.`,ua:`Конкретний сценарій із кроками, вхідними даними та очікуваним результатом.`},starter:!1},{section:`10`,term:{en:`Test suite`,ua:`Набір тестів`},def:{en:`A group of tests run together.`,ua:`Група тестів, які запускають разом.`},starter:!1},{section:`10`,term:{en:`Mock`,ua:`Мок`},def:{en:`A test double that imitates a dependency and can verify how it was called.`,ua:`Тестова заміна залежності, що імітує її та може перевіряти виклики.`},starter:!1},{section:`10`,term:{en:`Stub`,ua:`Стаб`},def:{en:`A simple replacement that returns predetermined answers during a test.`,ua:`Проста заміна, яка під час тесту повертає заздалегідь задані відповіді.`},starter:!1},{section:`10`,term:{en:`Fixture`,ua:`Тестові дані (fixture)`},def:{en:`Prepared data or setup used to make tests repeatable.`,ua:`Заздалегідь підготовлені дані або стан для повторюваних тестів.`},starter:!1},{section:`10`,term:{en:`Regression`,ua:`Регресія`},def:{en:`A bug introduced when a change breaks something that previously worked.`,ua:`Помилка, коли нова зміна ламає те, що раніше працювало.`},starter:!1},{section:`10`,term:{en:`TDD`,ua:`Розробка через тести (TDD)`},def:{en:`A practice of writing a failing test before implementing the behavior and then improving the code.`,ua:`Практика, коли спочатку пишуть тест, який не проходить, далі реалізують функцію й покращують код.`},starter:!1},{section:`10`,term:{en:`BDD`,ua:`Розробка через поведінку (BDD)`},def:{en:`Describing desired system behavior with shared examples that developers and stakeholders can understand.`,ua:`Опис очікуваної поведінки на прикладах, зрозумілих і розробникам, і замовникам.`},starter:!1},{section:`10`,term:{en:`Test coverage`,ua:`Покриття тестами`},def:{en:`A measure of what code or behavior tests exercise; high coverage alone does not prove quality.`,ua:`Показник того, яку частину коду чи поведінки перевіряють тести; високий відсоток не гарантує якість.`},starter:!1},{section:`10`,term:{en:`Linting`,ua:`Лінтинг`},def:{en:`Automatic checks for suspicious code and agreed coding rules.`,ua:`Автоматична перевірка підозрілих конструкцій і правил написання коду.`},starter:!1},{section:`10`,term:{en:`Formatting`,ua:`Форматування коду`},def:{en:`Applying consistent spacing, indentation, and layout to source code.`,ua:`Єдині правила відступів, пробілів та зовнішнього вигляду коду.`},starter:!1},{section:`10`,term:{en:`Refactoring`,ua:`Рефакторинг`},def:{en:`Improving a code's internal structure without intentionally changing its observable behavior.`,ua:`Покращення внутрішньої структури коду без навмисної зміни його зовнішньої поведінки.`},starter:!1},{section:`10`,term:{en:`Technical debt`,ua:`Технічний борг`},def:{en:`Extra future work caused by shortcuts or design choices that make changes harder.`,ua:`Додаткова майбутня робота через спрощення або рішення, що ускладнюють зміни.`},starter:!1},{section:`10`,term:{en:`Static analysis`,ua:`Статичний аналіз`},def:{en:`Checking code for problems without running the program.`,ua:`Перевірка коду на проблеми без запуску програми.`},starter:!1},{section:`10`,term:{en:`Code smell`,ua:`Ознака проблемного коду`},def:{en:`A warning sign that code may be hard to understand, test, or maintain.`,ua:`Ознака того, що код може бути складним для розуміння, тестування чи підтримки.`},starter:!1},{section:`10`,term:{en:`Contract testing`,ua:`Контрактне тестування`},def:{en:`Checking that services agree on the data and behavior of their shared API.`,ua:`Перевірка, що сервіси однаково розуміють дані та поведінку спільного API.`},starter:!1},{section:`11`,term:{en:`Authentication`,ua:`Автентифікація`},def:{en:`Checking who a user is, such as verifying a password or passkey.`,ua:`Перевірка особи користувача, наприклад за паролем або ключем доступу.`},starter:!1},{section:`11`,term:{en:`Authorization`,ua:`Авторизація`},def:{en:`Checking what an already identified user is allowed to do.`,ua:`Перевірка, які дії дозволені користувачу після встановлення його особи.`},starter:!1},{section:`11`,term:{en:`Permission`,ua:`Дозвіл`},def:{en:`A specific right, such as viewing reports or deleting posts.`,ua:`Конкретне право, наприклад переглядати звіти чи видаляти дописи.`},starter:!1},{section:`11`,term:{en:`Role`,ua:`Роль`},def:{en:`A named set of permissions, such as Admin, Editor, or Viewer.`,ua:`Іменований набір прав, наприклад Адміністратор, Редактор або Читач.`},starter:!1},{section:`11`,term:{en:`Principle of least privilege`,ua:`Принцип мінімальних привілеїв`},def:{en:`Give people and programs only the access they need for their tasks.`,ua:`Надавайте людям і програмам лише ті права, які потрібні для роботи.`},starter:!1},{section:`11`,term:{en:`Encryption`,ua:`Шифрування`},def:{en:`Turning readable information into protected data that requires a key to read.`,ua:`Перетворення зрозумілих даних на захищені, які можна прочитати за допомогою ключа.`},starter:!1},{section:`11`,term:{en:`Hashing`,ua:`Хешування`},def:{en:`Turning data into a fixed-size fingerprint; a cryptographic hash is designed to be one-way.`,ua:`Перетворення даних на «відбиток» фіксованої довжини; криптографічний хеш створено як односторонню операцію.`},starter:!1},{section:`11`,term:{en:`Password hashing`,ua:`Хешування паролів`},def:{en:`Storing password-verification data using a slow, salted password-hashing algorithm rather than plain text.`,ua:`Збереження перевірочних даних пароля через спеціальний алгоритм із сіллю, а не у відкритому вигляді.`},starter:!1},{section:`11`,term:{en:`Salt`,ua:`Сіль для хешування`},def:{en:`A unique random value mixed into a password before hashing to make reused passwords harder to attack in bulk.`,ua:`Унікальне випадкове значення, додане до пароля перед хешуванням, щоб ускладнити масові атаки.`},starter:!1},{section:`11`,term:{en:`TLS`,ua:`Протокол TLS`},def:{en:`A protocol that encrypts connections, widely used in HTTPS.`,ua:`Протокол шифрування з’єднань, який широко використовується в HTTPS.`},starter:!1},{section:`11`,term:{en:`OAuth 2.0`,ua:`OAuth 2.0`},def:{en:`A framework for granting an app limited access to resources without giving it your password.`,ua:`Механізм надання застосунку обмеженого доступу до ресурсів без передавання йому вашого пароля.`},starter:!1},{section:`11`,term:{en:`OpenID Connect (OIDC)`,ua:`OpenID Connect`},def:{en:`An identity layer built on OAuth 2.0 that supports user sign-in.`,ua:`Шар ідентифікації поверх OAuth 2.0, який підтримує вхід користувачів.`},starter:!1},{section:`11`,term:{en:`Multi-factor authentication (MFA)`,ua:`Багатофакторна автентифікація`},def:{en:`Verifying identity with at least two different factors, such as a password and a device.`,ua:`Перевірка особи щонайменше двома різними чинниками, наприклад паролем і пристроєм.`},starter:!1},{section:`11`,term:{en:`Session`,ua:`Сесія користувача`},def:{en:`A period of interaction whose state lets a system recognize a user across requests.`,ua:`Період взаємодії, стан якого допомагає системі впізнавати користувача між запитами.`},starter:!1},{section:`11`,term:{en:`Access token`,ua:`Токен доступу`},def:{en:`A credential a client presents to prove it has been granted particular access.`,ua:`Облікові дані, які клієнт пред’являє для підтвердження наданого доступу.`},starter:!1},{section:`11`,term:{en:`Vulnerability`,ua:`Вразливість`},def:{en:`A weakness in software or setup that an attacker might misuse.`,ua:`Слабке місце в коді чи налаштуваннях, яким може скористатися нападник.`},starter:!1},{section:`11`,term:{en:`Exploit`,ua:`Експлуатація вразливості`},def:{en:`A technique or code that uses a security weakness to cause unwanted behavior.`,ua:`Спосіб або код, що використовує вразливість для небажаних дій.`},starter:!1},{section:`11`,term:{en:`XSS`,ua:`Міжсайтовий скриптинг (XSS)`},def:{en:`A flaw that lets attacker-controlled script run in another user's browser.`,ua:`Помилка, через яку скрипт нападника може виконатися у браузері іншого користувача.`},starter:!1},{section:`11`,term:{en:`CSRF`,ua:`Підробка міжсайтового запиту (CSRF)`},def:{en:`An attack that tricks a signed-in browser into sending an unwanted request.`,ua:`Атака, коли браузер авторизованого користувача змушують надіслати небажаний запит.`},starter:!1},{section:`11`,term:{en:`SQL injection`,ua:`SQL-ін’єкція`},def:{en:`A flaw where unsafe input changes a database query in ways the developer did not intend.`,ua:`Помилка, коли небезпечне введення змінює SQL-запит не так, як задумав розробник.`},starter:!1},{section:`11`,term:{en:`OWASP`,ua:`OWASP`},def:{en:`A security community that publishes widely used guidance and lists of application risks.`,ua:`Спільнота з кібербезпеки, що публікує відомі рекомендації та переліки ризиків застосунків.`},starter:!1},{section:`11`,term:{en:`Secret`,ua:`Секрет, конфіденційний ключ`},def:{en:`Sensitive data such as API keys, private keys, or passwords that should not be publicly exposed.`,ua:`Чутливі дані, як-от API-ключі, приватні ключі та паролі, які не можна публікувати.`},starter:!1},{section:`11`,term:{en:`Threat modeling`,ua:`Моделювання загроз`},def:{en:`Thinking systematically about who might attack a system, how, and what protections are needed.`,ua:`Системний аналіз того, хто й як може атакувати систему та який захист потрібен.`},starter:!1},{section:`11`,term:{en:`API key`,ua:`API-ключ`},def:{en:`A credential used to identify or authenticate a calling app; it must be protected when secret.`,ua:`Ключ для ідентифікації або автентифікації застосунку під час звернення до API; секретні ключі треба захищати.`},starter:!1},{section:`12`,term:{en:`Deployment`,ua:`Розгортання`},def:{en:`Making a new build of software available in an environment where it will run.`,ua:`Розміщення нової збірки програми в середовищі, де вона працюватиме.`},starter:!0},{section:`12`,term:{en:`Hosting`,ua:`Хостинг`},def:{en:`Providing the computers and network services that keep a website or app available.`,ua:`Надання комп’ютерних і мережевих ресурсів, щоб сайт або застосунок був доступним.`},starter:!1},{section:`12`,term:{en:`Cloud computing`,ua:`Хмарні обчислення`},def:{en:`Renting computing resources, such as servers or storage, over the internet.`,ua:`Оренда обчислювальних ресурсів через інтернет: серверів, сховищ тощо.`},starter:!1},{section:`12`,term:{en:`Environment`,ua:`Середовище`},def:{en:`A particular setup where software runs, with its own configuration and data.`,ua:`Окреме налаштування для роботи програми з власними параметрами й даними.`},starter:!1},{section:`12`,term:{en:`Local development`,ua:`Локальна розробка`},def:{en:`Running and changing software on a developer's own computer.`,ua:`Запуск і зміна програми на власному комп’ютері розробника.`},starter:!1},{section:`12`,term:{en:`Development environment`,ua:`Середовище розробки`},def:{en:`A setup for actively building and debugging software.`,ua:`Середовище, у якому активно пишуть і налагоджують програму.`},starter:!1},{section:`12`,term:{en:`Staging`,ua:`Тестове передпродуктивне середовище`},def:{en:`A place to test a nearly finished release before real users receive it.`,ua:`Середовище для перевірки майже готового релізу перед випуском для користувачів.`},starter:!1},{section:`12`,term:{en:`Production`,ua:`Продуктивне середовище (продакшн)`},def:{en:`The live environment used by actual customers.`,ua:`Робоче середовище, яким користуються справжні клієнти.`},starter:!1},{section:`12`,term:{en:`Container`,ua:`Контейнер`},def:{en:`An isolated package that runs software with the dependencies it needs.`,ua:`Ізольоване середовище запуску програми з потрібними їй залежностями.`},starter:!1},{section:`12`,term:{en:`Docker`,ua:`Docker`},def:{en:`A popular platform for building and running containers.`,ua:`Популярна платформа для створення та запуску контейнерів.`},starter:!1},{section:`12`,term:{en:`Container image`,ua:`Образ контейнера`},def:{en:`A packaged filesystem and instructions used to start a container.`,ua:`Упаковані файли та інструкції, з яких запускають контейнер.`},starter:!1},{section:`12`,term:{en:`Kubernetes`,ua:`Kubernetes`},def:{en:`A system for deploying and managing containerized applications across machines.`,ua:`Система для розгортання та керування контейнерними застосунками на багатьох машинах.`},starter:!1},{section:`12`,term:{en:`CI`,ua:`Безперервна інтеграція (CI)`},def:{en:`Automatically building and testing changes as developers combine their work.`,ua:`Автоматична збірка й тестування змін під час об’єднання роботи розробників.`},starter:!1},{section:`12`,term:{en:`CD`,ua:`Безперервна доставка або розгортання (CD)`},def:{en:`Automating release preparation or deployment after code passes checks.`,ua:`Автоматизація підготовки релізу або його розгортання після перевірок.`},starter:!1},{section:`12`,term:{en:`Pipeline`,ua:`Конвеєр автоматизації`},def:{en:`A chain of automated steps, such as install, test, build, deploy.`,ua:`Послідовність автоматичних кроків: встановити, протестувати, зібрати, розгорнути.`},starter:!1},{section:`12`,term:{en:`Infrastructure as code (IaC)`,ua:`Інфраструктура як код`},def:{en:`Managing servers and cloud resources using versioned configuration files.`,ua:`Керування серверами й хмарними ресурсами через файли конфігурації під контролем версій.`},starter:!1},{section:`12`,term:{en:`Load balancer`,ua:`Балансувальник навантаження`},def:{en:`A component that spreads requests across multiple servers or instances.`,ua:`Компонент, що розподіляє запити між кількома серверами чи екземплярами.`},starter:!1},{section:`12`,term:{en:`Logging`,ua:`Журналювання`},def:{en:`Recording events and messages that help developers understand what happened.`,ua:`Запис подій і повідомлень, за якими можна зрозуміти, що відбулося.`},starter:!1},{section:`12`,term:{en:`Monitoring`,ua:`Моніторинг`},def:{en:`Regularly observing whether a system is healthy and performing well.`,ua:`Постійне спостереження за станом і продуктивністю системи.`},starter:!1},{section:`12`,term:{en:`Observability`,ua:`Спостережуваність`},def:{en:`The ability to understand a system's internal state from logs, metrics, and traces.`,ua:`Можливість зрозуміти внутрішній стан системи за журналами, метриками та трасуваннями.`},starter:!1},{section:`12`,term:{en:`Metric`,ua:`Метрика`},def:{en:`A numeric measurement of system behavior, such as response time or error rate.`,ua:`Числовий показник роботи системи, наприклад час відповіді чи частка помилок.`},starter:!1},{section:`12`,term:{en:`Trace`,ua:`Трасування запиту`},def:{en:`A record showing the path of an operation across parts of a system.`,ua:`Запис шляху однієї операції через різні частини системи.`},starter:!1},{section:`12`,term:{en:`Rollback`,ua:`Відкат`},def:{en:`Returning to an earlier working version after a bad release.`,ua:`Повернення до попередньої робочої версії після невдалого релізу.`},starter:!1},{section:`12`,term:{en:`Uptime`,ua:`Час доступності`},def:{en:`The amount or percentage of time a service is available.`,ua:`Час або відсоток часу, протягом якого сервіс доступний.`},starter:!1},{section:`12`,term:{en:`Outage`,ua:`Збій доступності`},def:{en:`A period when a service is partly or completely unavailable.`,ua:`Період, коли сервіс частково або повністю недоступний.`},starter:!1},{section:`12`,term:{en:`SLA`,ua:`Угода про рівень сервісу (SLA)`},def:{en:`A formal commitment about service quality, sometimes including consequences if it is missed.`,ua:`Формальна домовленість щодо якості сервісу, іноді з наслідками за її порушення.`},starter:!1},{section:`12`,term:{en:`SLO`,ua:`Ціль рівня сервісу (SLO)`},def:{en:`A measurable reliability target, such as 99.9% successful requests.`,ua:`Вимірювана ціль надійності, наприклад 99,9% успішних запитів.`},starter:!1},{section:`12`,term:{en:`RPO`,ua:`Ціль втрати даних (RPO)`},def:{en:`The maximum acceptable amount of recent data loss, measured in time.`,ua:`Максимально припустима втрата останніх даних, виміряна часом.`},starter:!1},{section:`12`,term:{en:`RTO`,ua:`Ціль часу відновлення (RTO)`},def:{en:`The maximum acceptable time to restore a service after a disruption.`,ua:`Максимально припустимий час відновлення сервісу після збою.`},starter:!1},{section:`13`,term:{en:`Distributed system`,ua:`Розподілена система`},def:{en:`A system where several computers cooperate to provide one service.`,ua:`Система, у якій кілька комп’ютерів спільно забезпечують один сервіс.`},starter:!1},{section:`13`,term:{en:`Replication`,ua:`Реплікація`},def:{en:`Keeping copies of data on multiple machines for availability or performance.`,ua:`Зберігання копій даних на кількох машинах задля доступності чи швидкодії.`},starter:!1},{section:`13`,term:{en:`Sharding`,ua:`Шардинг`},def:{en:`Splitting a dataset across different machines so each stores only part of it.`,ua:`Розподіл набору даних між машинами, кожна з яких зберігає лише частину.`},starter:!1},{section:`13`,term:{en:`Partitioning`,ua:`Секціонування даних`},def:{en:`Dividing data into separate parts to manage storage or queries more effectively.`,ua:`Поділ даних на окремі частини для зручнішого зберігання й виконання запитів.`},starter:!1},{section:`13`,term:{en:`Consistency`,ua:`Узгодженість даних`},def:{en:`Rules about what values different readers can observe as data changes.`,ua:`Правила того, які значення бачать різні читачі під час зміни даних.`},starter:!1},{section:`13`,term:{en:`Eventual consistency`,ua:`Узгодженість із часом`},def:{en:`Copies of data may briefly differ but are expected to converge if updates stop and systems recover.`,ua:`Копії даних можуть тимчасово відрізнятися, але згодом мають узгодитися за відсутності нових змін і після відновлення системи.`},starter:!1},{section:`13`,term:{en:`Strong consistency`,ua:`Сильна узгодженість`},def:{en:`A guarantee that reads follow a strict visibility rule for completed writes; the exact guarantee depends on the model.`,ua:`Гарантія суворих правил видимості завершених записів; точне значення залежить від моделі узгодженості.`},starter:!1},{section:`13`,term:{en:`Idempotency`,ua:`Ідемпотентність`},def:{en:`Repeating the same operation has the same intended effect as doing it once, such as avoiding duplicate charges.`,ua:`Повторення тієї самої операції має той самий очікуваний ефект, що й один виклик, наприклад без подвійної оплати.`},starter:!1},{section:`13`,term:{en:`Retry`,ua:`Повторна спроба`},def:{en:`Trying a failed operation again, usually only when doing so is safe.`,ua:`Повторне виконання операції після помилки, зазвичай лише коли це безпечно.`},starter:!1},{section:`13`,term:{en:`Backoff`,ua:`Затримка між спробами`},def:{en:`Waiting progressively longer between retries to avoid overloading a failing service.`,ua:`Поступове збільшення пауз між спробами, щоб не перевантажити проблемний сервіс.`},starter:!1},{section:`13`,term:{en:`Timeout`,ua:`Тайм-аут`},def:{en:`A limit on how long a program waits for an operation before treating it as too slow.`,ua:`Межа часу очікування, після якої операцію вважають надто повільною.`},starter:!1},{section:`13`,term:{en:`Circuit breaker`,ua:`Автоматичний запобіжник`},def:{en:`A pattern that temporarily stops calls to a failing service and later checks if it recovered.`,ua:`Шаблон, що тимчасово зупиняє виклики проблемного сервісу й пізніше перевіряє його відновлення.`},starter:!1},{section:`13`,term:{en:`CAP theorem`,ua:`Теорема CAP`},def:{en:`Under a network partition, a distributed data system cannot simultaneously guarantee both availability and strong single-copy consistency.`,ua:`За мережевого розділення розподілена система даних не може одночасно гарантувати і доступність, і сувору узгодженість єдиної копії.`},starter:!1},{section:`13`,term:{en:`ACID`,ua:`Властивості транзакцій ACID`},def:{en:`Four transaction properties: atomicity, consistency, isolation, and durability.`,ua:`Чотири властивості транзакцій: атомарність, узгодженість, ізоляція, довговічність.`},starter:!1},{section:`13`,term:{en:`BASE`,ua:`Модель BASE`},def:{en:`An approach that accepts looser immediate consistency to support availability in some distributed systems.`,ua:`Підхід, що в деяких розподілених системах допускає менш сувору миттєву узгодженість заради доступності.`},starter:!1},{section:`13`,term:{en:`Saga`,ua:`Шаблон Saga`},def:{en:`A way to coordinate several local transactions, with compensating actions if later steps fail.`,ua:`Спосіб узгодити кілька локальних транзакцій із компенсаційними діями, якщо подальший крок не вдався.`},starter:!1},{section:`13`,term:{en:`Consensus`,ua:`Консенсус`},def:{en:`A way for several machines to agree on a value or sequence of decisions despite failures.`,ua:`Спосіб, за яким кілька машин погоджують значення чи послідовність рішень попри збої.`},starter:!1},{section:`13`,term:{en:`Concurrency`,ua:`Конкурентне виконання`},def:{en:`Multiple tasks making progress during overlapping periods, not necessarily at the exact same instant.`,ua:`Виконання кількох задач у проміжки часу, що перекриваються, не обов’язково одночасно.`},starter:!1},{section:`13`,term:{en:`Race condition`,ua:`Стан гонитви`},def:{en:`A bug where the result depends on the unpredictable timing of competing operations.`,ua:`Помилка, коли результат залежить від непередбачуваного порядку виконання операцій.`},starter:!1},{section:`13`,term:{en:`Deadlock`,ua:`Взаємне блокування`},def:{en:`A situation where tasks wait on one another and none can continue.`,ua:`Ситуація, коли задачі чекають одна на одну й жодна не може продовжити роботу.`},starter:!1},{section:`14`,term:{en:`Artificial intelligence (AI)`,ua:`Штучний інтелект (ШІ)`},def:{en:`Software that performs tasks associated with human intelligence, such as recognizing patterns or generating text.`,ua:`Програми, що виконують задачі, пов’язані з інтелектом людини: розпізнавання образів або створення тексту.`},starter:!1},{section:`14`,term:{en:`Machine learning (ML)`,ua:`Машинне навчання`},def:{en:`A way to build systems that learn patterns from data instead of following only hand-written rules.`,ua:`Спосіб створення систем, які виявляють закономірності в даних, а не лише виконують задані вручну правила.`},starter:!1},{section:`14`,term:{en:`Large language model (LLM)`,ua:`Велика мовна модель (LLM)`},def:{en:`An AI model trained to process and generate language and often code.`,ua:`Модель ШІ, навчена працювати з мовою та часто з програмним кодом.`},starter:!1},{section:`14`,term:{en:`Prompt`,ua:`Промпт, інструкція для ШІ`},def:{en:`The message or instructions given to an AI model.`,ua:`Повідомлення чи інструкції, які передають моделі ШІ.`},starter:!1},{section:`14`,term:{en:`Prompt engineering`,ua:`Проєктування промптів`},def:{en:`Writing and improving instructions so an AI model produces useful results.`,ua:`Створення та вдосконалення інструкцій, щоб ШІ давав корисний результат.`},starter:!1},{section:`14`,term:{en:`Context`,ua:`Контекст`},def:{en:`Information available to the AI about the task, such as requirements and relevant files.`,ua:`Інформація, доступна ШІ для задачі: вимоги, потрібні файли тощо.`},starter:!1},{section:`14`,term:{en:`Context window`,ua:`Контекстне вікно`},def:{en:`The limited amount of text or tokens a model can consider in one interaction.`,ua:`Обмежений обсяг тексту або токенів, який модель може врахувати в одній взаємодії.`},starter:!1},{section:`14`,term:{en:`AI token`,ua:`Токен мовної моделі`},def:{en:`A small unit of text that a language model processes; it may be a word or part of one.`,ua:`Невелика одиниця тексту, яку обробляє мовна модель; це може бути слово або його частина.`},starter:!1},{section:`14`,term:{en:`AI model`,ua:`Модель ШІ`},def:{en:`A trained mathematical system that produces outputs from inputs.`,ua:`Навчена математична система, що формує результат на основі вхідних даних.`},starter:!1},{section:`14`,term:{en:`Inference`,ua:`Інференс, виконання моделі`},def:{en:`Using a trained AI model to generate an answer or prediction.`,ua:`Використання навченої моделі ШІ для створення відповіді чи прогнозу.`},starter:!1},{section:`14`,term:{en:`AI agent`,ua:`ШІ-агент`},def:{en:`An AI-driven system that can plan steps, use tools, and act toward a goal within its permissions.`,ua:`Система на основі ШІ, що може планувати кроки, застосовувати інструменти й діяти в межах наданих прав.`},starter:!1},{section:`14`,term:{en:`Hallucination`,ua:`Галюцинація ШІ`},def:{en:`A convincing AI-generated statement that is incorrect or unsupported.`,ua:`Переконлива відповідь ШІ, яка є неправильною або нічим не підтвердженою.`},starter:!1},{section:`14`,term:{en:`RAG`,ua:`Генерація з пошуком (RAG)`},def:{en:`An approach that gives an AI model retrieved documents or data before it answers.`,ua:`Підхід, коли ШІ перед відповіддю отримує знайдені документи чи дані.`},starter:!1},{section:`14`,term:{en:`Embedding`,ua:`Векторне представлення`},def:{en:`A numeric representation of meaning used to compare the similarity of text or other data.`,ua:`Числове представлення змісту, що допомагає порівнювати схожість текстів чи інших даних.`},starter:!1},{section:`14`,term:{en:`Vector database`,ua:`Векторна база даних`},def:{en:`A database optimized for storing and searching similarity-based numeric representations.`,ua:`База даних, пристосована до зберігання та пошуку схожих числових представлень.`},starter:!1},{section:`14`,term:{en:`Tool calling`,ua:`Виклик інструментів ШІ`},def:{en:`Letting an AI system request an external function, such as searching files or running a test.`,ua:`Можливість ШІ звернутися до зовнішньої функції, наприклад пошуку файлів або запуску тестів.`},starter:!1},{section:`14`,term:{en:`Prompt injection`,ua:`Ін’єкція промпту`},def:{en:`An attack where untrusted content tries to override an AI system's instructions.`,ua:`Атака, коли недовірений текст намагається підмінити інструкції системи ШІ.`},starter:!1},{section:`14`,term:{en:`Human-in-the-loop`,ua:`Людина в контурі контролю`},def:{en:`A workflow where a person reviews or approves important AI-generated decisions or actions.`,ua:`Процес, у якому людина перевіряє або погоджує важливі рішення й дії ШІ.`},starter:!1},{section:`14`,term:{en:`Specification`,ua:`Специфікація`},def:{en:`A precise description of what a system should do and how success will be checked.`,ua:`Точний опис того, що система має робити та як перевіряти результат.`},starter:!1},{section:`14`,term:{en:`Guardrail`,ua:`Захисне обмеження`},def:{en:`A rule or control that limits unsafe or incorrect actions by an AI system.`,ua:`Правило чи механізм, що обмежує небезпечні або неправильні дії ШІ.`},starter:!1},{section:`14`,term:{en:`Evaluation (eval)`,ua:`Оцінювання ШІ`},def:{en:`A structured check of how reliably an AI system performs defined tasks.`,ua:`Структурована перевірка того, наскільки надійно ШІ виконує визначені завдання.`},starter:!1},{section:`14`,term:{en:`Benchmark`,ua:`Порівняльний тест`},def:{en:`A standardized set of tasks or measurements used to compare systems.`,ua:`Стандартизований набір завдань чи вимірювань для порівняння систем.`},starter:!1},{section:`14`,term:{en:`MCP`,ua:`Протокол контексту моделей (MCP)`},def:{en:`A protocol that lets AI applications connect to external tools and information sources through common interfaces.`,ua:`Протокол, за яким ШІ-застосунки підключають зовнішні інструменти та джерела інформації через спільні інтерфейси.`},starter:!1},{section:`15`,term:{en:`MVP`,ua:`Мінімально життєздатний продукт (MVP)`},def:{en:`The smallest usable product that can test a real idea with actual users.`,ua:`Найменша придатна до використання версія продукту, яка перевіряє ідею на реальних користувачах.`},starter:!1},{section:`15`,term:{en:`Prototype`,ua:`Прототип`},def:{en:`An early model used to explore or demonstrate an idea, often not production-ready.`,ua:`Рання модель для перевірки або демонстрації ідеї, часто неготова для реальних користувачів.`},starter:!1},{section:`15`,term:{en:`Proof of concept (PoC)`,ua:`Перевірка здійсненності ідеї (PoC)`},def:{en:`A small experiment to test whether a technical idea can work.`,ua:`Невеликий експеримент, який перевіряє, чи може технічна ідея працювати.`},starter:!1},{section:`15`,term:{en:`Stakeholder`,ua:`Зацікавлена сторона`},def:{en:`A person or group affected by a product or its decisions, such as users or business owners.`,ua:`Людина чи група, на яку впливає продукт або рішення щодо нього: користувачі, власники бізнесу тощо.`},starter:!1},{section:`15`,term:{en:`Acceptance criteria`,ua:`Критерії приймання`},def:{en:`Specific conditions that must be met before a task is considered complete.`,ua:`Чіткі умови, які мають виконуватися, щоб задачу вважали завершеною.`},starter:!1},{section:`15`,term:{en:`Agile`,ua:`Гнучкі підходи до розробки`},def:{en:`A family of approaches focused on short feedback loops and adapting to change.`,ua:`Група підходів із короткими циклами зворотного зв’язку й готовністю до змін.`},starter:!1},{section:`15`,term:{en:`Sprint`,ua:`Спринт`},def:{en:`A fixed-length period of planned work in Scrum, often one or two weeks.`,ua:`Фіксований період запланованої роботи в Scrum, часто один-два тижні.`},starter:!1},{section:`15`,term:{en:`Backlog`,ua:`Беклог, перелік задач`},def:{en:`An ordered list of work the team may do, including features, bugs, and improvements.`,ua:`Упорядкований список потенційної роботи команди: функцій, помилок і покращень.`},starter:!1},{section:`15`,term:{en:`Roadmap`,ua:`Дорожня карта`},def:{en:`A high-level view of planned product goals and their likely sequence.`,ua:`Загальний план цілей продукту та очікуваного порядку їх досягнення.`},starter:!1},{section:`15`,term:{en:`Estimate`,ua:`Оцінка обсягу роботи`},def:{en:`A prediction of how much time, effort, or money a task may require.`,ua:`Приблизний прогноз часу, зусиль або коштів для виконання задачі.`},starter:!1},{section:`15`,term:{en:`ADR`,ua:`Запис архітектурного рішення (ADR)`},def:{en:`A short document recording a technical decision, alternatives, and reasons.`,ua:`Короткий документ із технічним рішенням, альтернативами та поясненням вибору.`},starter:!1},{section:`15`,term:{en:`Build vs buy`,ua:`Створити чи придбати`},def:{en:`Deciding whether to develop a capability yourself or use an existing product or service.`,ua:`Вибір між власною розробкою можливості й використанням готового продукту чи сервісу.`},starter:!1},{section:`15`,term:{en:`User story`,ua:`Історія користувача`},def:{en:`A short description of a need from a user's point of view, such as “As a guest, I want to book a room”.`,ua:`Короткий опис потреби з погляду користувача, наприклад «Як гість, хочу забронювати номер».`},starter:!1},{section:`15`,term:{en:`Definition of Done`,ua:`Критерії завершеності`},def:{en:`A shared checklist for when work is truly finished, including tests and review.`,ua:`Спільний перелік умов, після виконання яких роботу дійсно вважають завершеною.`},starter:!1}];var r={sections:a,terms:n};export{n,r,a as t};